	limitReached, storeErr := store.FeedLimitReached(userID)
	if storeErr != nil {
		return locale.NewLocalizedErrorWrapper(storeErr, "error.database_error", storeErr)
	}
	if limitReached {
		return locale.NewLocalizedErrorWrapper(storage.ErrFeedLimitReached, feedLimitReachedMessage)
	}
	return nil
}

